# Smart Kitchen Safety System

An IoT-based safety system built using ESP8266 and various sensors to monitor kitchen environments for flammable gas leaks (LPG/Methane) and smoke. When threshold limits are crossed, it sounds a buzzer, shuts off the gas supply solenoid, and sends warnings to users.

---

# Wiring Connection Diagram

```text
  [MQ-4 Sensor Analog Out]  ----> A0 (ESP8266)
  [MQ-2 Sensor Digital Out] ----> D2 (ESP8266)
  [Relay Module Control Pin]----> D5 (ESP8266) ----> Controls 12V Solenoid Valve
  [Piezo Buzzer positive]   ----> D7 (ESP8266)
  [SIM900 GSM TX / RX]      ----> D3 / D4 (SoftwareSerial)
```

---

# Arduino C++ Source Code (`kitchen_safety.ino`)

The complete C++ implementation to compile and flash using Arduino IDE:

```cpp
#include <SoftwareSerial.h>

// Pins Definition
#define GAS_PIN A0        // MQ-4 Analog Input pin
#define SMOKE_PIN D2      // MQ-2 Digital Input pin
#define RELAY_PIN D5      // Controls Gas Solenoid Valve (LOW = OPEN, HIGH = CLOSED)
#define BUZZER_PIN D7     // Warning Piezo Buzzer

// GSM SoftwareSerial Configuration
#define GSM_RX D3
#define GSM_TX D4
SoftwareSerial gsmSerial(GSM_RX, GSM_TX);

// Safety Thresholds
const int GAS_THRESHOLD = 380; // Analog value above which gas is detected
bool isEmergency = false;

void setup() {
  Serial.begin(115200);
  gsmSerial.begin(9600);

  pinMode(GAS_PIN, INPUT);
  pinMode(SMOKE_PIN, INPUT);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  // Set initial valve state to open
  digitalWrite(RELAY_PIN, LOW);
  digitalWrite(BUZZER_PIN, LOW);

  Serial.println("Smart Kitchen Safety System booting up...");
  delay(10000); // Warm up sensors (MQ-series need warming up)
  Serial.println("System Active.");
}

void loop() {
  int gasValue = analogRead(GAS_PIN);
  int smokeActive = digitalRead(SMOKE_PIN); // MQ-2 active low digital output

  Serial.print("MQ-4 Gas Value: ");
  Serial.println(gasValue);

  // Check emergency criteria
  if (gasValue > GAS_THRESHOLD || smokeActive == LOW) {
    if (!isEmergency) {
      triggerEmergency(gasValue);
    }
  } else {
    if (isEmergency) {
      clearEmergency();
    }
  }

  delay(1000);
}

void triggerEmergency(int gasLevel) {
  isEmergency = true;
  Serial.println("!!! EMERGENCY DETECTED !!!");

  // 1. Instantly trigger solenoid shutoff valve (Close valve)
  digitalWrite(RELAY_PIN, HIGH);

  // 2. Play warning pattern on buzzer
  digitalWrite(BUZZER_PIN, HIGH);

  // 3. Send SMS notification to homeowner
  sendAlertSMS(gasLevel);
}

void clearEmergency() {
  isEmergency = false;
  Serial.println("Kitchen environment stabilized. Resuming normal operations.");

  // 1. Reset valve to open
  digitalWrite(RELAY_PIN, LOW);

  // 2. Disable buzzer
  digitalWrite(BUZZER_PIN, LOW);
}

void sendAlertSMS(int gasValue) {
  Serial.println("Sending Emergency SMS Alert...");

  gsmSerial.println("AT+CMGF=1"); // Set GSM SMS mode to text
  delay(1000);

  gsmSerial.println("AT+CMGS=\"+919876543210\""); // Replace with user phone number
  delay(1000);

  gsmSerial.print("DANGER ALERT! High concentration of gas/smoke detected in your kitchen. Current analog level: ");
  gsmSerial.print(gasValue);
  gsmSerial.println(". Solenoid gas valve closed automatically.");

  delay(100);
  gsmSerial.write(26); // Send Ctrl+Z character to transmit message
  delay(5000);

  Serial.println("Alert SMS dispatched successfully.");
}
```

